mapper.delete:
delete from FLOW_FORECAST_CONFIG
where QUERY_DATE = to_date(#{queryDate,jdbcType=VARCHAR},'yyyy-mm-dd')
  and DEP_TYPE = #{depType,jdbcType=VARCHAR}
  and FLOW_TYPE = #{flowType,jdbcType=VARCHAR}
  and TARGET_TYPE = #{targetType,jdbcType=VARCHAR}

mapper.select:
select sdl.item_code targetType, nvl(to_char(ffc.query_date,'yyyy-mm-dd'),#{queryDate}) queryDate, nvl(ffc.dep_type,#{depType}) depType, nvl(ffc.flow_type,#{flowType}) flowType, ffc.target_timeone targetTimeone, ffc.target_timetwo targetTimetwo, ffc.target_timethree targetTimethree, ffc.target_timefour targetTimefour, ffc.target_timefive targetTimefive, ffc.target_timesix targetTimesix from sys_datadict_list sdl left join (select * from FLOW_FORECAST_CONFIG f where f.query_date = to_date(#{queryDate},'yyyy-mm-dd') and f.dep_type = #{depType} and f.flow_type = #{flowType}) ffc on sdl.item_code = ffc.target_type where sdl.dict_code = #{targetType}
AND sdl.item_code in
#{item}
order by sdl.order_no

select sum(tmp.sgAmount) targetTimeoneSG, sum(tmp.shAmount) targetTimeoneSH, sum(tmp.sgAmount)- sum(tmp.shAmount) targetTimeone, tmp.finprod_name targetName from (select decode(tfpdt.ps,#{PS_C2,jdbcType=VARCHAR},tfpdt.trade_amt,0) sgAmount, decode(tfpdt.ps,#{PS_C4,jdbcType=VARCHAR},tfpdt.trade_amt,0) shAmount, fp.finprod_name, fp.finprod_id from fin_product fp left join ( SELECT * FROM trd_fin_product_deal_total WHERE ps in (#{PS_C2,jdbcType=VARCHAR},#{PS_C4,jdbcType=VARCHAR}) and trade_date between to_date(#{queryDateBegin}, 'yyyy - mm - dd') and to_date(#{queryDateEnd}, 'yyyy - mm - dd')) tfpdt on tfpdt.finprod_id = fp.finprod_id and tfpdt.is_cancel = 'N' and tfpdt.p_trade_id is null where fp.finprod_id in ('F16_0900099C93','F16_0800099C91','F16_1100099C88','F16_1300099C89','F16_1801ZQ0244','F16_1801ZQ0406') union all select decode(tfpdt.ps,#{PS_C1,jdbcType=VARCHAR},tfpdt.trade_amt,#{PS_C2,jdbcType=VARCHAR},tfpdt.trade_amt,0) sgAmount, decode(tfpdt.ps,#{PS_C4,jdbcType=VARCHAR},tfpdt.trade_amt,0) shAmount, fp.finprod_name, fp.finprod_id from fin_product fp left join ( SELECT * FROM trd_fin_product_deal_total WHERE ps in (#{PS_C1,jdbcType=VARCHAR},#{PS_C2,jdbcType=VARCHAR},#{PS_C4,jdbcType=VARCHAR}) and trade_date between to_date(#{queryDateBegin}, 'yyyy - mm - dd') and to_date(#{queryDateEnd}, 'yyyy - mm - dd')) tfpdt on tfpdt.finprod_id = fp.finprod_id and tfpdt.is_cancel = 'N' and tfpdt.p_trade_id is null where fp.finprod_id = 'F16_1801LB0001') tmp where 1=1
and (tmp.finprod_id in
null) or tmp.finprod_id in (
#{item}
)
group by tmp.finprod_name

     	     select 
     		   count(0)
		       from FLOW_FORECAST_CONFIG ffc
		       where ffc.query_date = to_date(#{queryDate},'yyyy-mm-dd')
		       and ffc.dep_type = #{depType}
		       and ffc.flow_type = #{flowType}
